import json, sys
params = json.load(sys.stdin)

def convert(value):
    if isinstance(value, dict):
        return value
    elif isinstance(value, str):
        return value.casefold()
    else:
        return type(value)(value casefold())

result = {key: convert(value) for key, value in params.items()}
print(json.dumps(result))
